// ============================================================
// Payslip Sync — control tables (master database only)
// services/sync/schema.js
//
// Source of the migration config/sql/migrations/<ts>_sync_control_tables.sql
// (generated by scripts/sync-make-migration.js). Also used by tests and by
// checkControlTables() at start-up.
// ============================================================

const TABLES = {
  sync_exporters: `
    exporter_id   VARCHAR(100) NOT NULL,
    name          VARCHAR(200) NULL,
    key_id        VARCHAR(64)  NOT NULL,
    public_key    TEXT         NOT NULL,
    registered_by VARCHAR(100) NULL,
    registered_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    active        TINYINT(1)   NOT NULL DEFAULT 1,
    deactivated_by VARCHAR(100) NULL,
    deactivated_at DATETIME    NULL,
    PRIMARY KEY (exporter_id, key_id),
    KEY idx_sync_exporters_active (exporter_id, active)`,

  sync_packages: `
    id                 BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    fingerprint        VARCHAR(20)  NOT NULL,
    payload_sha256     CHAR(64)     NOT NULL,
    exporter_id        VARCHAR(100) NOT NULL,
    seq                INT          NOT NULL,
    base_seq           INT          NULL,
    kind               VARCHAR(20)  NOT NULL,
    period             CHAR(6)      NULL,
    databases_json     TEXT         NULL,
    header_json        MEDIUMTEXT   NOT NULL,
    bytes              BIGINT       NOT NULL,
    chunk_size         INT          NOT NULL,
    chunk_count        INT          NOT NULL,
    file_path          VARCHAR(500) NULL,
    uploaded_by        VARCHAR(100) NULL,
    upload_started_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    upload_finished_at DATETIME     NULL,
    status             VARCHAR(20)  NOT NULL DEFAULT 'uploading',
    reject_reason      VARCHAR(500) NULL,
    applied_at         DATETIME     NULL,
    rolled_back_at     DATETIME     NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uk_sync_packages_fp (fingerprint),
    KEY idx_sync_packages_seq (exporter_id, status, seq)`,

  sync_upload_chunks: `
    fingerprint VARCHAR(20) NOT NULL,
    chunk_no    INT         NOT NULL,
    bytes       INT         NOT NULL,
    received_at DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (fingerprint, chunk_no)`,

  sync_runs: `
    id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    run_uuid    CHAR(36)     NOT NULL,
    package_id  BIGINT UNSIGNED NOT NULL,
    status      VARCHAR(20)  NOT NULL DEFAULT 'received',
    stage       VARCHAR(200) NULL,
    started_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    finished_at DATETIME     NULL,
    live_at     DATETIME     NULL,
    error       TEXT         NULL,
    error_code  VARCHAR(50)  NULL,
    summary     MEDIUMTEXT   NULL,
    started_by  VARCHAR(100) NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uk_sync_runs_uuid (run_uuid),
    KEY idx_sync_runs_package (package_id)`,

  sync_table_state: `
    database_name VARCHAR(30)  NOT NULL,
    table_name    VARCHAR(64)  NOT NULL,
    scope         VARCHAR(100) NOT NULL DEFAULT '',
    last_run_id   BIGINT UNSIGNED NULL,
    row_count     BIGINT       NULL,
    table_hash    VARCHAR(80)  NULL,
    applied_at    DATETIME     NULL,
    PRIMARY KEY (database_name, table_name, scope)`,

  sync_publications: `
    database_name VARCHAR(30)  NOT NULL,
    period        CHAR(6)      NOT NULL,
    status        VARCHAR(20)  NOT NULL,
    staff_count   INT          NULL,
    total_net     DECIMAL(20,4) NULL,
    package_id    BIGINT UNSIGNED NULL,
    run_id        BIGINT UNSIGNED NULL,
    prepared_at   DATETIME     NULL,
    published_by  VARCHAR(100) NULL,
    published_at  DATETIME     NULL,
    withdrawn_by  VARCHAR(100) NULL,
    withdrawn_at  DATETIME     NULL,
    rolled_back_by VARCHAR(100) NULL,
    rolled_back_at DATETIME    NULL,
    PRIMARY KEY (database_name, period),
    KEY idx_sync_publications_status (status)`,
};

function createStatements(qualify = (t) => t) {
  return Object.entries(TABLES).map(
    ([name, body]) =>
      `CREATE TABLE IF NOT EXISTS ${qualify(name)} (${body}\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4`,
  );
}

/** Throws a clear error if a control table is missing. */
async function checkControlTables(db) {
  const master = db.masterSchema();
  const [rows] = await db.query(
    `SELECT TABLE_NAME AS t FROM INFORMATION_SCHEMA.TABLES
     WHERE TABLE_SCHEMA = ? AND TABLE_NAME LIKE 'sync\\_%'`,
    [master],
  );
  const have = new Set(rows.map((r) => r.t.toLowerCase()));
  const missing = Object.keys(TABLES).filter((t) => !have.has(t));
  if (missing.length) {
    const err = new Error(
      `Sync control tables missing in ${master}: ${missing.join(", ")}. Run npm run migrate:up.`,
    );
    err.code = "sync-tables-missing";
    throw err;
  }
}

module.exports = { TABLES, createStatements, checkControlTables };
